package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Stream;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class LmdbRunCollectorTest {

	private static final int[] SPOC = { 0, 1, 2, 3 };
	private static final int[] OSPC = { 2, 0, 1, 3 };

	@TempDir
	Path directory;

	private final ExecutorService executor = Executors.newFixedThreadPool(3);

	@AfterEach
	void shutDown() {
		executor.shutdownNow();
	}

	@ParameterizedTest
	@ValueSource(ints = { 520, 4110 })
	void completedRunsBoundFanInWithoutConcealingDuplicateRecords(int inputRows) throws Exception {
		try (LmdbRunCollector collector = new LmdbRunCollector("bounded", directory,
				new int[][] { SPOC, OSPC }, 4, 1, Runnable::run)) {
			Map<List<Long>, Integer> expected = new HashMap<>();
			for (int i = 0; i < inputRows; i++) {
				long object = i % 2 == 0 ? Long.MIN_VALUE + 1 : 19;
				collector.add(i % 13, 7, object, 0);
				expected.merge(List.of((long) (i % 13), 7L, object, 0L), 1, Integer::sum);
				collector.commit();
			}
			List<LmdbSortedRuns.Runs> completed = collector.completeRuns();
			assertThat(collector.completeRuns()).isEqualTo(completed);
			for (int order = 0; order < completed.size(); order++) {
				int[] fields = order == 0 ? SPOC : OSPC;
				for (int replay = 0; replay < 2; replay++) {
					int count = 0;
					Map<List<Long>, Integer> actual = new HashMap<>();
					long[] previous = null;
					try (LmdbSortedRuns.Merge merge = new LmdbSortedRuns.Merge(completed.get(order), fields, false)) {
						long[] row = new long[4];
						while (merge.next(row)) {
							assertThat(row[0]).isBetween(0L, 12L);
							assertThat(row[1]).isEqualTo(7);
							assertThat(row[2]).isIn(Long.MIN_VALUE + 1, 19L);
							assertThat(row[3]).isZero();
							actual.merge(List.of(row[0], row[1], row[2], row[3]), 1, Integer::sum);
							if (previous != null) {
								for (int field : fields) {
									int comparison = Long.compareUnsigned(previous[field], row[field]);
									assertThat(comparison).isLessThanOrEqualTo(0);
									if (comparison != 0) {
										break;
									}
								}
							}
							previous = row.clone();
							count++;
						}
					}
					assertThat(actual).isEqualTo(expected);
					assertThat(count).as("value-run duplicate records must remain visible on every replay")
							.isEqualTo(inputRows);
				}
				assertThat(completed.get(order).files()).as("final merge has at most32 file readers")
						.hasSizeLessThanOrEqualTo(32);
			}
		}
		try (var files = Files.list(directory)) {
			assertThat(files).isEmpty();
		}
	}

	@Test
	void rolledBackRowsNeverReachARunAndEveryOrderSeesTheCommittedRows() throws Exception {
		try (LmdbRunCollector collector = new LmdbRunCollector("t", directory, new int[][] { SPOC, OSPC }, 7, 2,
				executor)) {
			long expectedSum = 0;
			for (int chunk = 0; chunk < 10; chunk++) {
				for (int i = 0; i < 5; i++) {
					long s = 1_000 - (chunk * 5L + i);
					collector.add(s, 2, chunk, 0);
				}
				if (chunk % 3 == 2) {
					collector.rollback();
				} else {
					collector.commit();
					for (int i = 0; i < 5; i++) {
						expectedSum += 1_000 - (chunk * 5L + i);
					}
				}
			}
			assertThat(collector.committedRows()).isEqualTo(35);
			List<LmdbSortedRuns.Runs> runs = collector.completeRuns();
			assertThat(runs).hasSize(2);

			List<Long> subjects = new ArrayList<>();
			try (LmdbSortedRuns.Merge merge = new LmdbSortedRuns.Merge(runs.get(0), SPOC, true)) {
				long[] row = new long[4];
				while (merge.next(row)) {
					subjects.add(row[0]);
				}
			}
			assertThat(subjects).hasSize(35).isSorted();
			assertThat(subjects.stream().mapToLong(Long::longValue).sum()).isEqualTo(expectedSum);

			List<Long> objects = new ArrayList<>();
			try (LmdbSortedRuns.Merge merge = new LmdbSortedRuns.Merge(runs.get(1), OSPC, true)) {
				long[] row = new long[4];
				while (merge.next(row)) {
					objects.add(row[2]);
				}
			}
			assertThat(objects).hasSize(35).isSorted().doesNotContain(2L, 5L, 8L);
		}
		try (Stream<Path> left = Files.list(directory)) {
			assertThat(left).as("close deletes every run file").isEmpty();
		}
	}

	@Test
	void anImportThatNeverFillsAChunkWritesNoRunFile() throws Exception {
		try (LmdbRunCollector collector = new LmdbRunCollector("t", directory, new int[][] { SPOC, OSPC }, 1_000, 2,
				executor)) {
			for (int i = 0; i < 35; i++) {
				collector.add(1_000 - i, 2, i % 7, 0);
			}
			collector.commit();
			List<LmdbSortedRuns.Runs> runs = collector.completeRuns();
			try (Stream<Path> spilled = Files.list(directory)) {
				assertThat(spilled).as("the final chunk is merged from memory").isEmpty();
			}
			List<long[]> bySubject = new ArrayList<>();
			try (LmdbSortedRuns.Merge merge = new LmdbSortedRuns.Merge(runs.get(0), SPOC, true)) {
				long[] row = new long[4];
				while (merge.next(row)) {
					bySubject.add(row.clone());
				}
			}
			assertThat(bySubject).hasSize(35);
			assertThat(bySubject.stream().map(row -> row[0]).toList()).isSorted();
			List<Long> objects = new ArrayList<>();
			try (LmdbSortedRuns.Merge merge = new LmdbSortedRuns.Merge(runs.get(1), OSPC, true)) {
				long[] row = new long[4];
				while (merge.next(row)) {
					objects.add(row[2]);
				}
			}
			assertThat(objects).hasSize(35).isSorted();
		}
	}

	@Test
	void aChunkLargerThanTheBufferGrowsInsteadOfSpillingProvisionalRows() throws Exception {
		try (LmdbRunCollector collector = new LmdbRunCollector("t", directory, new int[][] { SPOC }, 4, 1,
				executor)) {
			for (int i = 0; i < 10; i++) {
				collector.add(i, 0, 0, 0);
			}
			assertThat(collector.provisionalRows()).isEqualTo(10);
			collector.rollback();
			collector.add(42, 0, 0, 0);
			assertThatThrownBy(collector::completeRuns).isInstanceOf(IllegalStateException.class);
			collector.commit();
			List<LmdbSortedRuns.Runs> runs = collector.completeRuns();
			List<Long> subjects = new ArrayList<>();
			try (LmdbSortedRuns.Merge merge = new LmdbSortedRuns.Merge(runs.get(0), SPOC, true)) {
				long[] row = new long[4];
				while (merge.next(row)) {
					subjects.add(row[0]);
				}
			}
			assertThat(subjects).containsExactly(42L);
		}
	}
}
